### backend/app/api/endpoints/services.py
```python
from fastapi import APIRouter, Depends, HTTPException, Query
from sqlalchemy.orm import Session
from typing import Optional
from uuid import UUID

from app.core.database import get_db
from app.api.deps import get_current_user
from app.models.user import User
from app.models.service import Service
from app.schemas.service import (
    ServiceCreate,
    ServiceUpdate,
    ServiceResponse,
    ServiceListResponse,
)

router = APIRouter()

@router.get("/", response_model=ServiceListResponse)
async def list_services(
    page: int = Query(1, ge=1),
    limit: int = Query(20, ge=1, le=100),
    search: Optional[str] = None,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user),
):
    query = db.query(Service)

    if search:
        query = query.filter(Service.name.ilike(f"%{search}%"))

    total = query.count()
    items = query.offset((page - 1) * limit).limit(limit).all()

    return ServiceListResponse(
        items=items,
        total=total,
        page=page,
        limit=limit,
    )

@router.get("/{id}", response_model=ServiceResponse)
async def get_service(
    id: UUID,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user),
):
    item = db.query(Service).filter(Service.id == id).first()
    if not item:
        raise HTTPException(status_code=404, detail="Service not found")
    return item

@router.post("/", response_model=ServiceResponse, status_code=201)
async def create_service(
    data: ServiceCreate,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user),
):
    item = Service(**data.model_dump(), created_by=current_user.id)
    db.add(item)
    db.commit()
    db.refresh(item)
    return item

@router.put("/{id}", response_model=ServiceResponse)
async def update_service(
    id: UUID,
    data: ServiceUpdate,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user),
):
    item = db.query(Service).filter(Service.id == id).first()
    if not item:
        raise HTTPException(status_code=404, detail="Service not found")

    for field, value in data.model_dump(exclude_unset=True).items():
        setattr(item, field, value)

    db.commit()
    db.refresh(item)
    return item

@router.delete("/{id}", status_code=204)
async def delete_service(
    id: UUID,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user),
):
    item = db.query(Service).filter(Service.id == id).first()
    if not item:
        raise HTTPException(status_code=404, detail="Service not found")

    db.delete(item)
    db.commit()
```

