### frontend/src/hooks/useMenus.ts
```typescript
import useSWR from 'swr';
import { api } from '@/lib/api';

interface UseMenusOptions {
  search?: string;
  page?: number;
  limit?: number;
}

export function useMenus(options: UseMenusOptions = {}) {
  const { search, page = 1, limit = 20 } = options;

  const queryParams = new URLSearchParams();
  queryParams.set('page', page.toString());
  queryParams.set('limit', limit.toString());
  if (search) queryParams.set('search', search);

  const { data, error, isLoading, mutate } = useSWR(
    `/menus?${queryParams}`,
    api.get
  );

  const createMenu = async (data: any) => {
    await api.post('/menus', data);
    mutate();
  };

  const updateMenu = async (id: string, data: any) => {
    await api.put(`/menus/${id}`, data);
    mutate();
  };

  const deleteMenu = async (id: string) => {
    await api.delete(`/menus/${id}`);
    mutate();
  };

  return {
    menus: data?.items || [],
    total: data?.total || 0,
    isLoading,
    error,
    createMenu,
    updateMenu,
    deleteMenu,
  };
}
