### backend/app/api/endpoints/contacts.py
```python
from fastapi import APIRouter, Depends, HTTPException, Query
from sqlalchemy.orm import Session
from typing import Optional
from uuid import UUID

from app.core.database import get_db
from app.api.deps import get_current_user
from app.models.user import User
from app.models.contact import Contact
from app.schemas.contact import (
    ContactCreate,
    ContactUpdate,
    ContactResponse,
    ContactListResponse,
)

router = APIRouter()

@router.get("/", response_model=ContactListResponse)
async def list_contacts(
    page: int = Query(1, ge=1),
    limit: int = Query(20, ge=1, le=100),
    search: Optional[str] = None,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user),
):
    query = db.query(Contact)

    if search:
        query = query.filter(Contact.name.ilike(f"%{search}%"))

    total = query.count()
    items = query.offset((page - 1) * limit).limit(limit).all()

    return ContactListResponse(
        items=items,
        total=total,
        page=page,
        limit=limit,
    )

@router.get("/{id}", response_model=ContactResponse)
async def get_contact(
    id: UUID,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user),
):
    item = db.query(Contact).filter(Contact.id == id).first()
    if not item:
        raise HTTPException(status_code=404, detail="Contact not found")
    return item

@router.post("/", response_model=ContactResponse, status_code=201)
async def create_contact(
    data: ContactCreate,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user),
):
    item = Contact(**data.model_dump(), created_by=current_user.id)
    db.add(item)
    db.commit()
    db.refresh(item)
    return item

@router.put("/{id}", response_model=ContactResponse)
async def update_contact(
    id: UUID,
    data: ContactUpdate,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user),
):
    item = db.query(Contact).filter(Contact.id == id).first()
    if not item:
        raise HTTPException(status_code=404, detail="Contact not found")

    for field, value in data.model_dump(exclude_unset=True).items():
        setattr(item, field, value)

    db.commit()
    db.refresh(item)
    return item

@router.delete("/{id}", status_code=204)
async def delete_contact(
    id: UUID,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user),
):
    item = db.query(Contact).filter(Contact.id == id).first()
    if not item:
        raise HTTPException(status_code=404, detail="Contact not found")

    db.delete(item)
    db.commit()
```

