    MenuListResponse,
)

router = APIRouter()

@router.get("/", response_model=MenuListResponse)
async def list_menus(
    page: int = Query(1, ge=1),
    limit: int = Query(20, ge=1, le=100),
    search: Optional[str] = None,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user),
):
    query = db.query(Menu)

    if search:
        query = query.filter(Menu.name.ilike(f"%{search}%"))

    total = query.count()
    items = query.offset((page - 1) * limit).limit(limit).all()

    return MenuListResponse(
        items=items,
        total=total,
        page=page,
        limit=limit,
    )

@router.get("/{id}", response_model=MenuResponse)
async def get_menu(
    id: UUID,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user),
):
    item = db.query(Menu).filter(Menu.id == id).first()
    if not item:
        raise HTTPException(status_code=404, detail="Menu not found")
    return item

@router.post("/", response_model=MenuResponse, status_code=201)
async def create_menu(
    data: MenuCreate,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user),
):
    item = Menu(**data.model_dump(), created_by=current_user.id)
    db.add(item)
    db.commit()
    db.refresh(item)
    return item

@router.put("/{id}", response_model=MenuResponse)
async def update_menu(
    id: UUID,
    data: MenuUpdate,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user),
):
    item = db.query(Menu).filter(Menu.id == id).first()
    if not item:
        raise HTTPException(status_code=404, detail="Menu not found")

    for field, value in data.model_dump(exclude_unset=True).items():
        setattr(item, field, value)

    db.commit()
    db.refresh(item)
    return item

@router.delete("/{id}", status_code=204)
async def delete_menu(
    id: UUID,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user),
):
    item = db.query(Menu).filter(Menu.id == id).first()
    if not item:
        raise HTTPException(status_code=404, detail="Menu not found")

    db.delete(item)
    db.commit()
