### backend/app/api/endpoints/courses.py
```python
from fastapi import APIRouter, Depends, HTTPException, Query
from sqlalchemy.orm import Session
from typing import Optional
from uuid import UUID

from app.core.database import get_db
from app.api.deps import get_current_user
from app.models.user import User
from app.models.course import Course
from app.schemas.course import (
    CourseCreate,
    CourseUpdate,
    CourseResponse,
    CourseListResponse,
)

router = APIRouter()

@router.get("/", response_model=CourseListResponse)
async def list_courses(
    page: int = Query(1, ge=1),
    limit: int = Query(20, ge=1, le=100),
    search: Optional[str] = None,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user),
):
    query = db.query(Course)

    if search:
        query = query.filter(Course.name.ilike(f"%{search}%"))

    total = query.count()
    items = query.offset((page - 1) * limit).limit(limit).all()

    return CourseListResponse(
        items=items,
        total=total,
        page=page,
        limit=limit,
    )

@router.get("/{id}", response_model=CourseResponse)
async def get_course(
    id: UUID,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user),
):
    item = db.query(Course).filter(Course.id == id).first()
    if not item:
        raise HTTPException(status_code=404, detail="Course not found")
    return item

@router.post("/", response_model=CourseResponse, status_code=201)
async def create_course(
    data: CourseCreate,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user),
):
    item = Course(**data.model_dump(), created_by=current_user.id)
    db.add(item)
    db.commit()
    db.refresh(item)
    return item

@router.put("/{id}", response_model=CourseResponse)
async def update_course(
    id: UUID,
    data: CourseUpdate,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user),
):
    item = db.query(Course).filter(Course.id == id).first()
    if not item:
        raise HTTPException(status_code=404, detail="Course not found")

    for field, value in data.model_dump(exclude_unset=True).items():
        setattr(item, field, value)

    db.commit()
    db.refresh(item)
    return item

@router.delete("/{id}", status_code=204)
async def delete_course(
    id: UUID,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user),
):
    item = db.query(Course).filter(Course.id == id).first()
    if not item:
        raise HTTPException(status_code=404, detail="Course not found")

    db.delete(item)
    db.commit()
```

